class Solution {
    // {best if node robbed, best if node skipped}
    pair<int, int> go(TreeNode* n) {
        if (!n) return {0, 0};
        auto [lt, ls] = go(n->left);
        auto [rt, rs] = go(n->right);
        return {n->val + ls + rs, max(lt, ls) + max(rt, rs)};
    }
public:
    int rob(TreeNode* root) {
        auto [t, s] = go(root);
        return max(t, s);
    }
};
